"""
Музыка быстрее и без перебора.

  • Atlas больше не перебирает треки «похоже, не то» по словам запроса: на «что-нибудь поэпичнее»
    первой же заиграла «The Maze Runner», но в названии не было слова «epic» — и он менял ещё
    три раза. Теперь он просто называет, что заиграло; не то — поправишь.
  • Смена страницы результатов замечается сразу: раньше сравнение по средней яркости не видело
    её на тёмной странице Spotify, и каждый запуск ждал до упора (5–6 с вместо 1–2).
    Теперь считается доля изменившихся участков центральной колонки.
  • «Поставь какую-нибудь весёлую музыку» ищет «весёлую музыку», без «какую-нибудь».

    python apply_music8.py
    python apply_music8.py --rollback
"""
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
P8 = [('system_control.py', 'сравнение страниц: только центральная колонка, мельче сетка', '        img = pyautogui.screenshot(region=(l + int(w * 0.25), t + int(h * 0.15), int(w * 0.7), int(h * 0.3)))\n        return list(img.convert("L").resize((24, 8)).getdata())', '        # центральная колонка результатов: без боковой библиотеки и правой панели «Сейчас играет»\n        img = pyautogui.screenshot(region=(l + int(w * 0.07), t + int(h * 0.12), int(w * 0.65), int(h * 0.43)))\n        return list(img.convert("L").resize((48, 16)).getdata())'), ('system_control.py', 'сравнение страниц: доля изменившихся участков, а не средняя яркость', 'def _sig_diff(a, b) -> float:\n    if not a or not b or len(a) != len(b):\n        return 255.0\n    return sum(abs(x - y) for x, y in zip(a, b)) / len(a)', 'def _sig_diff(a, b) -> float:\n    """Сколько процентов участков картинки заметно изменилось. Страница Spotify почти вся тёмная,\n    меняются только обложки и надписи — средняя яркость этого почти не замечала."""\n    if not a or not b or len(a) != len(b):\n        return 100.0\n    return 100.0 * sum(1 for x, y in zip(a, b) if abs(x - y) > 12) / len(a)'), ('system_control.py', 'сравнение страниц: пороги под новую меру', '        if sig and (before is None or _sig_diff(sig, before) > 6):\n            if prev is not None and _sig_diff(sig, prev) < 3:', '        if sig and (before is None or _sig_diff(sig, before) > 0.6):        # неподвижная страница даёт ровно 0\n            if prev is not None and _sig_diff(sig, prev) < 0.3:'), ('system_control.py', 'без «похоже, не то»: Atlas называет, что заиграло, и не перебирает', '            return "playing" if _matches_request(query, title) else "other:" + title', '            return "playing"        # что заиграло — Atlas назовёт; перебор «не то» по словам приносил вред'), ('fast_commands.py', '«поставь какую-нибудь весёлую музыку» ищет «весёлую музыку»', '            query = what if stripped else ""', '            query = " ".join(re.sub(r"(?<![\\w-])(?:какую-нибудь|какую нибудь|какую-то|что-нибудь|что нибудь|"\n                                    r"любую|немного|мне)(?![\\w-])", " ", what).split()) if stripped else ""')]
TESTS = {'tests/test_spotify.py': '"""\nТесты музыки в Spotify (system_control.py): продолжить воспроизведение, найти кнопку Play\n(в том числе видимую только при наведении), снимок окна при неудаче.\nОкно Spotify, экран и клавиши — подставные: Windows и сам Spotify не нужны.\n\n    python tests/test_spotify.py\n"""\nimport functools\nimport os\nimport shutil\nimport sys\nimport tempfile\nimport traceback\nimport types\n\nfor _stream in (sys.stdout, sys.stderr):\n    try:\n        _stream.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nfrom PIL import Image, ImageDraw  # noqa: E402\n\nRECT = (100, 50, 1300, 850)                  # окно Spotify на экране\nS = {}\n\n\ndef reset(title="Spotify Premium", button="visible", key_works=True, space_works=True, avatar=True,\n          stale=False, title_on_click="Linkin Park - Numb", hidden=False, behind=False):\n    S.update(hidden=hidden, behind=behind, front=not behind, title=title, button=button, key_works=key_works, space_works=space_works, mouse=(5, 5),\n             clicks=[], keys=[], popen=[], hovered=False, avatar=avatar, stale=stale, switch_at=0.0,\n             title_on_click=title_on_click, old_clicks=0)\n\n\ndef _page_old():\n    import time                                      # до поиска и ещё секунду после — на экране прошлые результаты\n    return S["stale"] and (not S["popen"] or time.time() < S["switch_at"])\n\n\ndef _popen(cmd, shell=True):\n    import time\n    S["popen"].append(cmd)\n    if S["stale"]:\n        S["switch_at"] = time.time() + 1.0          # ещё секунду на экране прошлые результаты\n\n\ndef _click(x, y):\n    S["clicks"].append((x, y))\n    if _page_old():                                  # кнопка прошлого (играющего) результата = пауза\n        S["old_clicks"] += 1\n        S["title"] = "Spotify Premium"\n    else:\n        S["title"] = S["title_on_click"]\n\n\ndef screenshot(region):\n    l, t, w, h = region\n    if S.get("behind") and not S.get("front"):    # Spotify позади окна Atlas — на экране видно Atlas\n        return Image.new("RGB", (w, h), (10, 14, 40))\n    img = Image.new("RGB", (w, h), (18, 18, 18))\n    d = ImageDraw.Draw(img)\n    d.rectangle((40, 600, 140, 700), fill=(30, 215, 96))          # зелёная обложка слева — не кнопка\n    if S.get("stale") and S.get("small_change"):                  # как в жизни: меняются обложка и надпись\n        d.rectangle((int(0.08 * w), int(0.15 * h), int(0.14 * w), int(0.25 * h)),\n                    fill=(150, 70, 60) if _page_old() else (60, 90, 150))\n        d.rectangle((int(0.16 * w), int(0.18 * h), int(0.16 * w) + (180 if _page_old() else 110), int(0.21 * h)),\n                    fill=(230, 230, 230))\n    elif S.get("stale"):                                           # обложка лучшего результата: старая / новая\n        d.rectangle((int(0.30 * w), int(0.20 * h), int(0.42 * w), int(0.42 * h)),\n                    fill=(200, 40, 40) if _page_old() else (40, 60, 200))\n    if S.get("avatar"):                                            # зелёный аватар профиля «T» в шапке справа\n        d.ellipse((w - 60, 12, w - 24, 48), fill=(30, 215, 96))\n        d.ellipse((int(0.82 * w), int(0.20 * h), int(0.82 * w) + 34, int(0.20 * h) + 34), fill=(30, 215, 96))   # значок поменьше\n    mx, my = S["mouse"][0] - l, S["mouse"][1] - t\n    over_card = 0.25 * w <= mx <= 0.65 * w and 0.25 * h <= my <= 0.50 * h\n    S["hovered"] = S["hovered"] or over_card\n    if S["button"] == "genre":                                     # страница жанра, как на снимке пользователя\n        d.rectangle((int(0.07 * w), int(0.14 * h), int(0.72 * w), int(0.25 * h)), fill=(40, 40, 40))   # «Жанр» без кнопки\n        for i in range(5):\n            x0, y0 = int((0.07 + i * 0.085) * w), int(0.345 * h)\n            x1, y1 = x0 + int(0.07 * w), y0 + int(0.125 * h)\n            d.rectangle((x0, y0, x1, y1), fill=(90 + 30 * i, 60, 140))                                  # обложки\n            if x0 <= mx <= x1 and y0 <= my <= y1:                                                        # наведение\n                d.ellipse((x1 - 42, y1 - 42, x1 - 6, y1 - 6), fill=(30, 215, 96))                         # кнопка 36 px\n    if S["button"] == "visible" or (S["button"] == "hover" and over_card):\n        cx, cy = int(0.55 * w), int(0.40 * h)\n        d.ellipse((cx - 28, cy - 28, cx + 28, cy + 28), fill=(30, 215, 96))\n    return img\n\n\ndef install():\n    sys.modules["pyautogui"] = types.SimpleNamespace(\n        screenshot=screenshot,\n        position=lambda: S["mouse"],\n        moveTo=lambda x, y=None: S.update(mouse=(x, y) if y is not None else x),\n        click=_click,\n        press=lambda k: (S["keys"].append(k), S.update(title="Artist - Song") if S["space_works"] else None))\n\n\ndef load():\n    import importlib.util\n    spec = importlib.util.spec_from_file_location("system_control", os.path.join(ROOT, "system_control.py"))\n    m = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(m)\n    m._spotify_windows = lambda: [] if S.get("hidden") and not S["popen"] else [(1, S["title"], RECT)]\n    m._bring_to_front = lambda hwnd: (S.update(front=True), True)[1]\n\n    def media_key():\n        S["keys"].append("media")\n        if S["key_works"]:\n            S["title"] = "Artist - Song"\n    m._media_play_pause_key = media_key\n    m.subprocess = types.SimpleNamespace(Popen=_popen)\n    m._spotify_autoplay = functools.partial(m._spotify_autoplay, timeout=3)\n    m._spotify_resume_fast = functools.partial(m._spotify_resume, timeout=3)\n    return m\n\n\nTESTS = []\n\n\ndef test(fn):\n    TESTS.append(fn)\n    return fn\n\n\n@test\ndef play_music_resumes_when_paused():\n    reset()\n    r = M.play_on_spotify("")\n    assert S["popen"] == ["start spotify:"] and S["keys"] == ["media"] and "Artist - Song" in r, (r, S)\n\n\n@test\ndef already_playing_is_not_paused():\n    reset(title="Daft Punk - One More Time")\n    r = M.play_on_spotify("")\n    assert S["keys"] == [] and "уже играет" in r, (r, S["keys"])\n\n\n@test\ndef space_is_the_backup_when_media_key_does_nothing():\n    reset(key_works=False)\n    r = M.play_on_spotify("")\n    assert S["keys"] == ["media", "space"] and "Artist - Song" in r, (r, S["keys"])\n\n\n@test\ndef query_clicks_the_visible_button_and_restores_mouse():\n    reset(button="visible")\n    r = M.play_on_spotify("linkin park numb")\n    assert S["popen"] == ["start spotify:search:linkin%20park%20numb"] and len(S["clicks"]) == 1\n    x, y = S["clicks"][0]\n    assert abs(x - (RECT[0] + 0.55 * 1200)) < 15 and abs(y - (RECT[1] + 0.40 * 800)) < 15, S["clicks"]\n    assert "Linkin Park - Numb" in r and S["mouse"] == (5, 5)\n\n\n@test\ndef hover_reveals_the_button():\n    reset(button="hover")\n    r = M.play_on_spotify("numb")\n    assert S["hovered"] and len(S["clicks"]) == 1 and "Linkin Park - Numb" in r and S["mouse"] == (5, 5), (r, S)\n\n\n@test\ndef failure_saves_a_snapshot_for_tuning():\n    reset(button="none")\n    d = tempfile.mkdtemp()\n    cwd = os.getcwd()\n    try:\n        os.chdir(d)\n        r = M.play_on_spotify("numb")\n        shots = os.listdir(os.path.join(d, "logs"))\n    finally:\n        os.chdir(cwd)\n        shutil.rmtree(d, ignore_errors=True)\n    assert "не нашёл кнопку Play" in r and any(s.startswith("spotify_no_play_button") for s in shots), (r, shots)\n    assert not S["clicks"] and S["mouse"] == (5, 5)\n\n\n@test\ndef avatar_in_the_header_is_not_the_play_button():\n    reset(button="visible", avatar=True)\n    M.play_on_spotify("numb")\n    x, y = S["clicks"][0]\n    assert abs(x - (RECT[0] + 0.55 * 1200)) < 15 and abs(y - (RECT[1] + 0.40 * 800)) < 15, \\\n        f"нажал не туда: {S[\'clicks\']} (аватар в шапке или значок поменьше)"\n\n\n@test\ndef old_results_are_not_clicked():\n    reset(title="leadwave - unfortunately", stale=True, title_on_click="Maroon 5 - Animals")\n    r = M.play_on_spotify("animals maroon 5")\n    assert S["old_clicks"] == 0 and "Maroon 5 - Animals" in r, (r, S["old_clicks"])\n\n\n@test\ndef what_is_playing_is_named_without_second_guessing():\n    for q, title in (("epic cinematic music", "John Paesano - The Maze Runner"),\n                     ("animals maroon 5", "Earth, Wind & Fire - Boogie Wonderland")):\n        reset(title_on_click=title)\n        r = M.play_on_spotify(q)\n        assert r.startswith("Включил") and title in r and "не то" not in r, (q, r)\n\n\n@test\ndef page_change_is_noticed_quickly_even_if_small():\n    import time\n    reset(title="Two Steps From Hell - Victory", stale=True, title_on_click="Pharrell Williams - Happy")\n    S["small_change"] = True\n    short = M._spotify_autoplay\n    M._spotify_autoplay = functools.partial(short.func, timeout=12)     # ожидание как в жизни — до 4 с\n    t0 = time.time()\n    try:\n        r = M.play_on_spotify("happy music")\n    finally:\n        M._spotify_autoplay = short\n        S["small_change"] = False\n    took = time.time() - t0\n    assert S["old_clicks"] == 0 and "Happy" in r, (r, S["old_clicks"])\n    assert took < 2.8, f"смена страницы замечена слишком поздно: {took:.1f} с (ждал до упора)"\n\n\n@test\ndef mood_and_cyrillic_requests_are_not_second_guessed():\n    reset(title_on_click="Pharrell Williams - Happy")\n    assert M.play_on_spotify("upbeat happy music").startswith("Включил")\n    reset(title_on_click="Linkin Park - Numb")\n    assert M.play_on_spotify("линкин парк намб").startswith("Включил")\n\n\n@test\ndef genres_are_not_second_guessed():\n    for q, t in (("classic rock", "KISS - I Was Made For Lovin\' You"), ("Classic Rock Essentials", "Deep Purple - Smoke On The Water"),\n                 ("classic rock hits", "AC/DC - Highway to Hell"), ("animals", "Maroon 5 - Animals - Remix")):\n        reset(title_on_click=t)\n        r = M.play_on_spotify(q)\n        assert r.startswith("Включил") and "не то" not in r, (q, r)\n\n\n@test\ndef minimized_spotify_old_page_is_not_clicked():\n    reset(title="leadwave - unfortunately", stale=True, hidden=True, title_on_click="Maroon 5 - Animals")\n    r = M.play_on_spotify("animals maroon 5")\n    assert S["old_clicks"] == 0 and "Maroon 5 - Animals" in r, (r, S["old_clicks"])\n\n\n@test\ndef spotify_behind_atlas_old_page_is_not_clicked():\n    reset(title="Eminem - Superman", stale=True, behind=True, title_on_click="Lofi Girl - Snowman")\n    r = M.play_on_spotify("lofi beats")\n    assert S["old_clicks"] == 0 and "Lofi Girl" in r, (r, S["old_clicks"])\n\n\n@test\ndef genre_page_plays_a_playlist_card():\n    reset(button="genre", title_on_click="Lofi Girl - Snowman")\n    r = M.play_on_spotify("lofi")\n    assert len(S["clicks"]) == 1 and "Lofi Girl" in r and S["mouse"] == (5, 5), (r, S["clicks"])\n\n\n@test\ndef green_cover_on_the_left_is_not_a_button():\n    reset(button="none")\n    assert M._find_green_play(RECT) is None and M._find_green_play(RECT, x_from=0.2) is None\n\n\ndef main():\n    global M\n    install()\n    M = load()\n    ok = 0\n    for t in TESTS:\n        try:\n            t()\n            ok += 1\n            print(f"  ✓ {t.__name__}")\n        except Exception:\n            print(f"  ✗ {t.__name__}\\n" + "".join("      " + ln for ln in traceback.format_exc().splitlines(True)[-4:]))\n    print(f"\\nТестов пройдено: {ok} из {len(TESTS)}")\n    sys.stdout.flush()\n    sys.stderr.flush()\n    os._exit(0 if ok == len(TESTS) else 1)\n\n\nif __name__ == "__main__":\n    main()\n', 'tests/test_commands.py': '"""\nТесты быстрого пути (fast_commands.py) и слов управления (core/control_words.py).\n\n    python tests/test_commands.py                       — проверки поведения\n    python tests/test_commands.py --compare СТАРЫЙ.py   — старая и новая версии на одних фразах:\n                                                          любое расхождение = ошибка\n\nБез интернета и Windows: всё, что вызывает быстрый путь, заменено подставными функциями.\n"""\nimport importlib.util\nimport os\nimport sys\nimport traceback\nimport types\n\nfor _stream in (sys.stdout, sys.stderr):\n    try:\n        _stream.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nCALLS = []\nSTATE = {"game": False, "browser_open": False, "fail_open_app": False, "fail_text": "Приложение не найдено"}\n\n\ndef _rec(name, result=None):\n    def f(*a, **kw):\n        CALLS.append((name, a, kw))\n        if name == "open_app" and STATE["fail_open_app"]:\n            return STATE["fail_text"]\n        return result if result is not None else f"{name}: ok"\n    return f\n\n\ndef _browser(name):\n    def f(**kw):\n        CALLS.append((name, (), kw))\n        return f"{name}: ok" if STATE["browser_open"] else "Браузер не открыт."\n    return f\n\n\ndef _mod(name, **attrs):\n    m = types.ModuleType(name)\n    m.__dict__.update(attrs)\n    sys.modules[name] = m\n    return m\n\n\ndef install():\n    _mod("core.missions", start=lambda goal: (CALLS.append(("missions.start", (goal[:40],), {})), "M1")[1])\n    core = sys.modules.get("core") or _mod("core")\n    if not hasattr(core, "__path__"):\n        core.__path__ = [os.path.join(ROOT, "core")]\n    core.missions = sys.modules["core.missions"]\n    _mod("ui_state", shared_state={"chat_history": [("You", "сравни ноутбуки"), ("Atlas", "ок")]})\n    _mod("voice", get_response_language=lambda: "ru")\n    _mod("skills").__path__ = []\n    _mod("skills.fun", game_active=lambda: STATE["game"], guess_number=_rec("guess_number", "Больше!"),\n         tell_joke=_rec("tell_joke", "Шутка"), random_fact=_rec("random_fact", "Факт"))\n    _mod("file_search", _ORD={"первый": 1, "второй": 2, "третий": 3, "second": 2},\n         search_file_content=_rec("search_file_content"), open_found_file=_rec("open_found_file"),\n         open_search_result=_rec("open_search_result"), show_search_result_in_folder=_rec("show_search_result_in_folder"))\n    _mod("deep_links", launch_steam_game=_rec("launch_steam_game"), list_steam_games=_rec("list_steam_games"),\n         open_deep_link=_rec("open_deep_link"))\n    _mod("system_control", open_app=_rec("open_app"), close_app=_rec("close_app"),\n         play_on_spotify=_rec("play_on_spotify"), play_on_youtube_music=_rec("play_on_youtube_music"))\n    _mod("system_advanced", **{n: _rec(n) for n in ("set_volume", "volume_up", "volume_down", "mute_volume",\n                                                    "unmute_volume", "set_brightness", "lock_screen", "take_screenshot")})\n    _mod("media_control", **{n: _rec(n) for n in ("play_pause_media", "next_track", "previous_track")})\n    _mod("theme_control", set_theme=_rec("set_theme"))\n    _mod("browser_agent", **{n: _browser(n) for n in ("media_volume", "media_play_pause", "skip_intro", "next_episode",\n                                                      "media_player_fullscreen", "media_seek")})\n\n\ndef load(path, name):\n    spec = importlib.util.spec_from_file_location(name, path)\n    m = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(m)\n    return m\n\n\nPHRASES = [\n    "", "Открой блокнот", "открой блокнот и запиши список дел", "Открой блокнот, напиши привет", "открой гугл хром",\n    "открой фотошоп", "запусти Telegram", "открой фильм интерстеллар", "открой сайт хабр", "закрой хром",\n    "закрой хром и открой блокнот", "включи спокойную музыку", "включи музыку", "поставь джаз на спотифае",\n    "включи linkin park на ютуб музыке", "включи музыку и сделай громче", "play some music",\n    "в фоне сравни три ноутбука до 1000 долларов", "расскажи шутку", "шутка про котов", "tell me a joke about cats",\n    "расскажи интересный факт", "факт о космосе", "где файл про бюджет поездки",\n    "найди файл где я писал про стажировку", "покажи скриншот с ошибкой", "where is the file about the trip budget",\n    "open the file about taxes", "открой второй", "open the second one", "открой 3", "покажи второй в папке",\n    "открой файл про налоги", "запусти cyberpunk в стиме", "запусти игру ведьмак", "какие у меня игры",\n    "найди котиков на ютубе", "открой эйфелеву башню в википедии", "найди рецепт в интернете",\n    "громкость 50", "громкость на 30%", "громче", "тише", "выключи звук", "включи звук", "яркость 70",\n    "заблокируй экран", "сделай скриншот", "пауза", "продолжи", "пропусти заставку", "следующая серия",\n    "на весь экран", "перемотай вперёд", "назад", "следующий трек", "предыдущая песня", "тёмная тема",\n    "light mode", "какая погода", "что ты обо мне знаешь", "Атлас, выключись", "«Открой проводник»",\n    "open calculator", "launch steam", "открой второй файл", "volume 80", "brightness 40", "45",\n]\n\n\ndef run_all(mod):\n    out = []\n    for game in (False, True):\n        for browser in (False, True):\n            STATE.update(game=game, browser_open=browser)\n            for p in PHRASES:\n                CALLS.clear()\n                try:\n                    r = mod.try_fast_command(p)\n                except Exception as e:\n                    r = f"EXC {type(e).__name__}: {e}"\n                out.append(((game, browser, p), repr(r), repr(CALLS)))\n    STATE.update(game=False, browser_open=False)\n    return out\n\n\nTESTS = []\n\n\ndef test(fn):\n    TESTS.append(fn)\n    return fn\n\n\ndef fast(p, game=False, browser=False):\n    STATE.update(game=game, browser_open=browser)\n    CALLS.clear()\n    r = FC.try_fast_command(p)\n    STATE.update(game=False, browser_open=False)\n    return r, [c[0] for c in CALLS], CALLS\n\n\n@test\ndef apps_open_by_alias_and_multi_part_goes_to_brain():\n    r, names, calls = fast("Открой блокнот")\n    assert names == ["open_app"] and calls[0][1] == ("блокнот",)\n    assert fast("открой гугл хром")[2][0][1] == ("хром",)\n    assert fast("открой блокнот и запиши список дел")[0] is None\n    assert fast("Открой блокнот, напиши привет")[0] is None\n    assert fast("открой фильм интерстеллар")[0] is None, "фильм — не приложение"\n\n\n@test\ndef failed_app_goes_to_brain():\n    STATE["fail_open_app"] = True\n    try:\n        for text in ("Приложение не найдено", "Не нашёл приложение «фотошоп»", "Не могу найти ярлык"):\n            STATE["fail_text"] = text\n            assert fast("открой фотошоп")[0] is None, text\n    finally:\n        STATE.update(fail_open_app=False, fail_text="Приложение не найдено")\n\n\n@test\ndef wake_word_at_the_start_is_understood():\n    assert fast("атлас, включи музыку")[2][0][:2] == ("play_on_spotify", ("",))\n    assert fast("Атлас! открой блокнот")[2][0][1] == ("блокнот",)\n    assert fast("atlas, open calculator")[2][0][1] == ("калькулятор",)\n\n\n@test\ndef music():\n    assert fast("включи спокойную музыку")[2][0][:2] == ("play_on_spotify", ("спокойную музыку",))\n    assert fast("включи музыку")[2][0][:2] == ("play_on_spotify", ("",))\n    assert fast("включи какую-нибудь музыку")[2][0][:2] == ("play_on_spotify", ("",)), "это «включи музыку», а не поиск"\n    assert fast("включи мне любую музыку")[2][0][:2] == ("play_on_spotify", ("",))\n    assert fast("поставь какую-нибудь веселую музыку")[2][0][:2] == ("play_on_spotify", ("веселую музыку",))\n    assert fast("включи linkin park на ютуб музыке")[1] == ["play_on_youtube_music"]\n    assert fast("включи музыку и сделай громче")[0] is None\n\n\n@test\ndef background_mission_joke_fact_and_game():\n    r, names, _ = fast("в фоне сравни три ноутбука до 1000 долларов")\n    assert r[0] == "speak" and "M1" in r[1] and names == ["missions.start"]\n    assert fast("шутка про котов")[2][0][:2] == ("tell_joke", ("котов",))\n    assert fast("расскажи интересный факт")[1] == ["random_fact"]\n    assert fast("45", game=True) == (("speak", "Больше!"), ["guess_number"], [("guess_number", (45,), {})])\n    assert fast("45")[0] is None\n\n\n@test\ndef files():\n    assert fast("найди файл где я писал про стажировку")[2][0][:2] == ("search_file_content", ("стажировку",))\n    assert fast("where is the file about the trip budget")[2][0][:2] == ("search_file_content", ("the trip budget",))\n    assert fast("открой второй")[2][0][:2] == ("open_search_result", ("второй",))\n    assert fast("покажи второй в папке")[1] == ["show_search_result_in_folder"]\n\n\n@test\ndef steam_services_volume_media():\n    assert fast("запусти cyberpunk в стиме")[2][0][:2] == ("launch_steam_game", ("cyberpunk",))\n    assert fast("найди котиков на ютубе")[2][0][:2] == ("open_deep_link", ("youtube", "котиков"))\n    assert fast("громкость на 30%")[2][0][:2] == ("set_volume", (30,))\n    assert fast("тише")[1] == ["media_volume", "volume_down"], "браузер закрыт → системная громкость"\n    assert fast("тише", browser=True)[1] == ["media_volume"]\n    assert fast("пауза")[1] == ["media_play_pause", "play_pause_media"]\n    assert fast("на весь экран")[0] is None, "без браузера решает модель"\n    assert fast("тёмная тема")[2][0][:2] == ("set_theme", ("dark",))\n\n\n@test\ndef unknown_goes_to_brain():\n    for p in ("какая погода", "что ты обо мне знаешь", "", "найди рецепт в интернете"):\n        assert fast(p)[0] is None, p\n\n\n@test\ndef control_words():\n    from core.control_words import is_stop, is_shutdown, normalize\n    assert normalize("Атлас, выключись, пожалуйста!") == "выключись"\n    assert is_shutdown("Атлас, выключись") and is_shutdown("go to sleep") and is_shutdown("Shut down.")\n    assert not is_shutdown("выключи музыку") and not is_shutdown("выключи свет в комнате")\n    assert is_stop("Стоп.") and is_stop("атлас, хватит") and is_stop("не надо")\n    assert not is_stop("стоп музыку")\n\n\ndef main():\n    global FC\n    install()\n    if "--compare" in sys.argv:\n        old = load(sys.argv[sys.argv.index("--compare") + 1], "fast_commands_old")\n        new = load(os.path.join(ROOT, "fast_commands.py"), "fast_commands_new")\n        a, b = run_all(old), run_all(new)\n        diffs = [(k, ra, rb, ca, cb) for (k, ra, ca), (_, rb, cb) in zip(a, b) if (ra, ca) != (rb, cb)]\n        for k, ra, rb, ca, cb in diffs[:15]:\n            print(f"  ✗ {k}\\n      было:  {ra} {ca}\\n      стало: {rb} {cb}")\n        print(f"Сравнение старой и новой версии: {len(a) - len(diffs)} из {len(a)} совпали")\n        sys.stdout.flush()\n        sys.stderr.flush()\n        os._exit(0 if not diffs else 1)\n    FC = load(os.path.join(ROOT, "fast_commands.py"), "fast_commands")\n    ok = 0\n    for t in TESTS:\n        try:\n            t()\n            ok += 1\n            print(f"  ✓ {t.__name__}")\n        except Exception:\n            print(f"  ✗ {t.__name__}\\n" + "".join("      " + ln for ln in traceback.format_exc().splitlines(True)[-5:]))\n    print(f"\\nТестов пройдено: {ok} из {len(TESTS)}")\n    sys.stdout.flush()\n    sys.stderr.flush()\n    os._exit(0 if ok == len(TESTS) else 1)\n\n\nif __name__ == "__main__":\n    main()\n'}
TOUCHED = ["system_control.py", "fast_commands.py"] + list(TESTS)


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel in TOUCHED:
        b = os.path.join(backup, *rel.split("/"))
        if os.path.exists(b):
            shutil.copy2(b, p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith("backup_music8_"))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if "near=None" not in open(p("system_control.py"), encoding="utf-8").read():
    sys.exit("Сначала поставь apply_music7.py.")

new, status = {}, []
for rel, what, old, repl in P8:
    s = new.get(rel) or open(p(rel), encoding="utf-8").read()
    if repl in s:
        status.append((what, "уже было"))
    elif s.count(old) == 1:
        s = s.replace(old, repl, 1)
        status.append((what, "ok"))
    else:
        status.append((what, "НЕ НАЙДЕНО"))
    new[rel] = s
for what, st in status:
    print(f"  {'!' if st == 'НЕ НАЙДЕНО' else '✓'} {what}" + ("" if st == "ok" else f" ({st})"))
if any(st == "НЕ НАЙДЕНО" for _, st in status):
    sys.exit("Код выглядит иначе, чем я ожидал — ничего не изменено. Пришли вывод.")
if all(st == "уже было" for _, st in status):
    sys.exit("Уже установлено.")

backup = p(time.strftime("backup_music8_%Y%m%d_%H%M%S"))
for rel in TOUCHED:
    os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
    shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, s in list(new.items()) + list(TESTS.items()):
    with open(p(rel), "w", encoding="utf-8", newline="\n") as f:
        f.write(s)

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [os.path.join("tests", f) for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    r = subprocess.run([sys.executable, p(suite)], cwd=ROOT, capture_output=True, text=True, encoding="utf-8",
                       errors="replace", timeout=300, env=env)
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", r.stdout + r.stderr)
    good = r.returncode == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} {suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        with open(p("music8_test_output.txt"), "w", encoding="utf-8") as f:
            f.write(r.stdout + "\n" + r.stderr)
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено. Пришли music8_test_output.txt.")
